package com.example.wecker.ui.theme

import android.app.Activity
import android.os.Build
import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.dynamicDarkColorScheme
import androidx.compose.material3.dynamicLightColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalContext

private val DarkColorScheme = darkColorScheme(
    primary = Purple80,
    secondary = PurpleGrey80,
    tertiary = Pink80
)

private val LightColorScheme = lightColorScheme(
    primary = Purple40,
    secondary = PurpleGrey40,
    tertiary = Pink40

    /* Other default colors to override
    background = Color(0xFFFFFBFE),
    surface = Color(0xFFFFFBFE),
    onPrimary = Color.White,
    onSecondary = Color.White,
    onTertiary = Color.White,
    onBackground = Color(0xFF1C1B1F),
    onSurface = Color(0xFF1C1B1F),
    */
)

@Composable
fun WeckerTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    // Dynamic color is available on Android 12+
    dynamicColor: Boolean = true,
    content: @Composable () -> Unit
) {
    val colorScheme = when {
        dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> {
            val context = LocalContext.current
            if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context)
        }

        darkTheme -> DarkColorScheme
        else -> LightColorScheme
    }

    MaterialTheme(
        colorScheme = colorScheme,
        typography = Typography,
        content = content
    )
}

package com.example.wecker.ui.theme
import androidx.compose.material3.MaterialTheme import androidx.compose.material3.darkColorScheme import androidx.compose.material3.lightColorScheme import androidx.compose.runtime.Composable
private val DarkColorScheme = darkColorScheme( primary = Purple40, onPrimary = NightText, secondary = PurpleGrey40, onSecondary = NightText, tertiary = Pink40, onTertiary = NightText, background = NightBlack, onBackground = NightText, surface = NightSurface, onSurface = NightText, surfaceVariant = NightSurfaceVariant, onSurfaceVariant = NightMutedText, error = NightError, onError = NightText )
private val LightColorScheme = lightColorScheme( primary = Purple40, onPrimary = NightText, secondary = PurpleGrey40, onSecondary = NightText, tertiary = Pink40, onTertiary = NightText, background = NightBlack, onBackground = NightText, surface = NightSurface, onSurface = NightText, surfaceVariant = NightSurfaceVariant, onSurfaceVariant = NightMutedText, error = NightError, onError = NightText )
@Composable fun WeckerTheme( darkTheme: Boolean = true, dynamicColor: Boolean = false, content: @Composable () -> Unit ) { // Feste Farben verhindern OEM-/Wallpaper-bedingte Abweichungen im Release. val colorScheme = if (darkTheme) DarkColorScheme else LightColorScheme
MaterialTheme( colorScheme = colorScheme, typography = Typography, content = content ) }
